W<-'work/2026-10-29-remaining-maps/mobility';library(ggplot2);library(grid)
for(mid in c('ASF-V06','ASF-V10','ASF-V28')){w<-file.path(W,mid);q<-jsonlite::fromJSON(file.path(w,'input-qc.json'));p<-readRDS(file.path(w,'plot.rds'));ragg::agg_png(file.path(w,'grob-measurement.png'),width=q$width_mm,height=q$height_mm,units='mm',res=200,background='white');g<-patchwork::patchworkGrob(p);labels<-character();sizes<-numeric();fix<-function(x){if(inherits(x,'text')){if(is.expression(x$label))x$label<-vapply(x$label,function(y)paste(deparse(y),collapse=''),character(1));x$gp$fontfamily<-'Arial';if(!is.null(x$gp$fontsize)){x$gp$fontsize<-pmax(6.5,x$gp$fontsize);sizes<<-c(sizes,x$gp$fontsize)};labels<<-c(labels,as.character(x$label))};if(length(x$grobs))x$grobs<-lapply(x$grobs,fix);if(length(x$children))x$children<-do.call(gList,lapply(x$children,fix));x};g<-fix(g);dev.off();saveRDS(g,file.path(w,'composed-vector-grob.rds'));wrapped<-ggplotify::as.ggplot(g)+theme(text=element_text(family='Arial',size=7),plot.margin=margin(0,0,0,0));saveRDS(wrapped,file.path(w,'render-object.rds'));jsonlite::write_json(list(labels=unique(labels[!is.na(labels)&nzchar(labels)]),point_sizes=sort(unique(sizes)),normalization='Actual text grobs explicitly Arial; minimum6.5pt.'),file.path(w,'text-manifest.json'),auto_unbox=TRUE,pretty=TRUE)}
